def count_weekday_occurrences(year, month, weekday):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    t = [0,3,2,5,0,3,5,1,4,6,2,4]
    count = 0
    for day in range(1, lengths[month-1]+1):
        y = year
        m = month
        if m < 3:
            y -= 1
        w = (y + y//4 - y//100 + y//400 + t[m-1] + day) % 7
        if w == weekday:
            count += 1
    return count

def format_date_tuple(date):
    y, m, d = date
    return f'{y:04d}-{m:02d}-{d:02d}'

def word_count_difference(text1, text2):
    c1 = {}
    for w in text1.split():
        c1[w] = c1.get(w, 0) + 1
    c2 = {}
    for w in text2.split():
        c2[w] = c2.get(w, 0) + 1
    keys = set(c1) | set(c2)
    return {k: c1.get(k, 0) - c2.get(k, 0) for k in keys}

def is_valid_iso_datetime(s):
    if s.count('T') != 1:
        return False
    date_part, time_part = s.split('T')
    dparts = date_part.split('-')
    if len(dparts) != 3:
        return False
    y, m, d = dparts
    if not (len(y) == 4 and y.isdigit() and len(m) == 2 and m.isdigit() and len(d) == 2 and d.isdigit()):
        return False
    year, month, day = int(y), int(m), int(d)
    if not (1 <= year <= 9999 and 1 <= month <= 12):
        return False
    leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    dim = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if not (1 <= day <= dim[month - 1]):
        return False
    tparts = time_part.split(':')
    if len(tparts) != 3:
        return False
    h, mi, sec = tparts
    if not (len(h) == 2 and h.isdigit() and len(mi) == 2 and mi.isdigit() and len(sec) == 2 and sec.isdigit()):
        return False
    return 0 <= int(h) <= 23 and 0 <= int(mi) <= 59 and 0 <= int(sec) <= 59

def center_text_block(lines, width):
    result = []
    for s in lines:
        if len(s) >= width:
            result.append(s)
        else:
            total = width - len(s)
            left = total // 2
            right = total - left
            result.append(' ' * left + s + ' ' * right)
    return result

def convert_spaces_to_underscores(s):
    import re
    return re.sub(r'\s+', '_', s.strip())

def meeting_overlap_minutes(s1, e1, s2, e2):
    start = max(s1, s2)
    end = min(e1, e2)
    return max(0, end - start)
